import * as M from './model.js';
import {knownIds} from './community-life.js';
import * as A from './academic-year.js';
export function data(s){return s.recordReview??={schema:1,reports:[],corrections:[]};}
export function draft(s,studentId,recordIndexes){const st=s.students.find(x=>x.id===studentId);if(!st)return {error:'학생을 선택해 주세요.'};const selected=[...new Set(recordIndexes)].map(i=>st.records[i]).filter(r=>r&&r.kind==='behavior'&&r.day>=s.academic.start&&r.day<=s.day);if(!selected.length)return {error:'이번 학년도에 관찰한 행동 누가기록을 선택해 주세요.'};const key=s.academic.year+'-'+A.term(s)+'-'+studentId,d=data(s);if(d.reports.some(r=>r.id===key&&r.locked))return {error:'확정된 기록은 정정 사유와 함께 수정해 주세요.'};const text=selected.map(r=>`${r.text.replace(/[。.!?]+$/,'')}.`).join(' ');const report={id:key,studentId,term:A.term(s),year:s.academic.year,text,evidence:selected.map(r=>({day:r.day,date:r.date,text:r.text,order:r.order})),locked:false,created:M.stamp(s),updated:M.stamp(s)};const i=d.reports.findIndex(r=>r.id===key);if(i>=0)d.reports[i]=report;else d.reports.push(report);return {ok:true,id:key};}
export function save(s,id,text,lock=false){const r=data(s).reports.find(r=>r.id===id);if(!r||r.locked||String(text).trim().length<8)return {error:'검토할 문장을 구체적으로 적어 주세요. 확정 후에는 정정 절차를 사용합니다.'};r.text=String(text).trim().slice(0,3000);r.updated=M.stamp(s);if(lock){r.locked=true;r.confirmed=M.stamp(s);}return {ok:true};}
export function correct(s,id,text,reason){const r=data(s).reports.find(r=>r.id===id);if(!r?.locked||String(reason).trim().length<5||String(text).trim().length<8)return {error:'확정한 기록·바꿀 내용·정정 사유가 필요합니다.'};data(s).corrections.push({id,from:r.text,to:String(text).slice(0,3000),reason:String(reason).slice(0,500),date:M.stamp(s)});r.text=String(text).slice(0,3000);r.updated=M.stamp(s);return {ok:true};}
export function valid(s){const d=s.recordReview;if(!d)return true;return d.schema===1&&Array.isArray(d.reports)&&d.reports.every(r=>knownIds(s).has(r.studentId)&&typeof r.text==='string'&&typeof r.locked==='boolean'&&Array.isArray(r.evidence)&&r.evidence.length>0&&r.evidence.every(e=>typeof e.text==='string'))&&Array.isArray(d.corrections);}
